import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十一卦 噬嗑 火雷噬嗑 離上震下","description":"周易 - 第二十一卦 噬嗑 火雷噬嗑 離上震下","frontmatter":{"title":"第二十一卦 噬嗑 火雷噬嗑 離上震下","description":"周易 - 第二十一卦 噬嗑 火雷噬嗑 離上震下"},"headers":[],"relativePath":"classics/zhouyi/022.md","filePath":"classics/zhouyi/022.md"}'),l={name:"classics/zhouyi/022.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="噬嗑" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑" aria-label="Permalink to “噬嗑”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。利用獄。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>頤中有物，曰噬嗑，噬嗑而亨。剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>雷電噬嗑；先王以明罰敕法。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>履校滅趾，無咎。象曰：履校滅趾，不行 也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>噬膚滅鼻，無咎。象曰：噬膚滅鼻，乘剛也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>噬臘肉，遇毒；小吝，無咎。象曰：遇毒，位不當也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>噬乾胏，得金矢，利艱貞，吉。象曰：利艱貞吉，未光也。六五：噬乾肉，得黃金，貞厲，無咎。象曰：貞厲無咎，得當也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>何校滅耳，兇。象曰：何校滅耳，聰不明也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
